mapper.select:
SELECT spu.id, spu.name, spu.brand, spu.model, spu.description, spu.is_limited, spu.release_date, spu.status, spu.create_time, MIN(sku.price) as min_price, MAX(sku.price) as max_price, COUNT(DISTINCT sku.id) as color_count, (SELECT COALESCE(SUM(ss.stock), 0) FROM shoe_sku_size ss INNER JOIN shoe_sku s ON ss.sku_id = s.id WHERE s.spu_id = spu.id) as total_stock, (SELECT COALESCE(SUM(od.number), 0) FROM order_detail od INNER JOIN orders o ON od.order_id = o.id WHERE od.spu_id = spu.id AND o.status != 7) as sales_count, GROUP_CONCAT(DISTINCT sku.color_name) as color_names, GROUP_CONCAT(DISTINCT c.name) as category_names, (SELECT sku2.image FROM shoe_sku sku2 WHERE sku2.spu_id = spu.id ORDER BY sku2.is_default DESC, sku2.id ASC LIMIT 1) as default_image FROM shoe_spu spu LEFT JOIN shoe_sku sku ON spu.id = sku.spu_id LEFT JOIN shoe_spu_category spuc ON spu.id = spuc.spu_id LEFT JOIN category c ON spuc.category_id = c.id
AND spu.name LIKE CONCAT('%', #{name}, '%')
AND spu.brand = #{brand}
AND spu.status = #{status}
AND spu.is_limited = #{isLimited}
AND spuc.category_id = #{categoryId}
AND spuc.category_id IN
#{id}
GROUP BY spu.id ORDER BY spu.release_date DESC, spu.create_time DESC

SELECT spu.id, spu.name, spu.brand, spu.model, spu.description, spu.is_limited, spu.release_date, spu.status, MIN(sku.price) as min_price, MAX(sku.price) as max_price, COUNT(DISTINCT sku.id) as color_count, (SELECT COALESCE(SUM(ss.stock), 0) FROM shoe_sku_size ss INNER JOIN shoe_sku s ON ss.sku_id = s.id WHERE s.spu_id = spu.id) as total_stock, (SELECT COALESCE(SUM(od.number), 0) FROM order_detail od INNER JOIN orders o ON od.order_id = o.id WHERE od.spu_id = spu.id AND o.status != 7) as sales_count, GROUP_CONCAT(DISTINCT sku.color_name) as color_names, GROUP_CONCAT(DISTINCT c.name) as category_names, (SELECT sku2.image FROM shoe_sku sku2 WHERE sku2.spu_id = spu.id ORDER BY sku2.is_default DESC, sku2.id ASC LIMIT 1) as default_image FROM shoe_spu spu INNER JOIN shoe_spu_category spuc ON spu.id = spuc.spu_id LEFT JOIN shoe_sku sku ON spu.id = sku.spu_id AND sku.status = 1 LEFT JOIN category c ON spuc.category_id = c.id WHERE spu.status = 1 AND spuc.category_id IN
#{id}
GROUP BY spu.id ORDER BY spu.release_date DESC, spu.create_time DESC
